head.script:
scwin.dateSum1 = function(colArr, dataType) {
    var hours = [];
    var mins = [];
    var secs = [];
    for (var i = 0; i < colArr.length; i++) {
        var times = colArr[i].split(":");
        hours.push(Number(times[0]) || 0);
        mins.push(Number(times[1]) || 0);
        secs.push(Number(times[2]) || 0);
    }
    var totalSecs = eval(secs.join("+")) + (60 * eval(mins.join("+"))) + (3600 * eval(hours.join("+")));
    var tempSecs = totalSecs;
    var ret_day = Math.floor(totalSecs / 86400);
    tempSecs = tempSecs % 86400;
    var ret_hour = Math.floor(tempSecs / 3600);
    tempSecs = tempSecs % 3600;
    var ret_min = Math.floor(tempSecs / 60);
    var ret_sec = tempSecs % 60;
    return ret_day + "d" + ret_hour + "h" + ret_min + "m" + ret_sec + "s";
};
scwin.unitTest = function() {
    //init
    // WebSquare.wUnit.start();
    //Test step 1. Source 탭에서 id=footer11 에 column14 expression 을 확인한다.
    //1. In the Source tab, check id = footer11 for column14 expression.
    //Verify step 1. expression = "custom (scwin.dateSum1, 'col2')
    //Test step 2. 브라우저에서 name2 컬럼의 footer 를 확인한다.
    //2. Check the footer of the name2 column in your browser.
    //Verify step 2. The sum of the time of the name2 columns is output to the footer.
    WebSquare.wUnit.addCommand("assert", "WebSquare.wUnit.getObjById('wq_uuid_3_column14').textContent != ''", "true");
    WebSquare.wUnit.addCommand("pause", "500");
    //Run  and stop
    WebSquare.wUnit.run();
    WebSquare.wUnit.stop();
}
scwin.onpageload2 = function() {
    if (typeof scwin.onpageload === "function") {
        scwin.onpageload();
    }
    window.f = [];
    for (var i = 1; i <= 21; i++) {
        if (i % 3 === 1) {
            f.push(i);
        } else {
            window.x = Math.floor(Math.random() * 24);
            window.y = Math.floor(Math.random() * 60);
            window.z = Math.floor(Math.random() * 60);
            if (x < 10) {
                x = "0" + x;
            }
            if (y < 10) {
                y = "0" + y;
            }
            if (z < 10) {
                z = "0" + z;
            }
            f.push(x + ":" + y + ":" + z);
        }
    }
    dataList1.setData(f);
    //Function 
    //Created by: Thuyet.Pham
    //Created date: 02-Mar-2018
    if (typeof scwin.unitTest === "function") {
        scwin.unitTest();
    }
}
